-- Référence MySQL 8+ ; générer les migrations Laravel et les tables Spatie.
-- Schéma relationnel de référence MySQL 8+, à implémenter avec des migrations Laravel.
-- Les contraintes de chevauchement/concurrence sont à implémenter dans la logique transactionnelle.
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, phone VARCHAR(40), first_name VARCHAR(160), email VARCHAR(255), origin_city VARCHAR(160), origin_country VARCHAR(160), address VARCHAR(255), notes TEXT, identification_type VARCHAR(60), identification_number VARCHAR(100));
CREATE TABLE room_types (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) UNIQUE NOT NULL, label VARCHAR(100) NOT NULL);
CREATE TABLE rooms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, number VARCHAR(30) UNIQUE NOT NULL, room_type_id BIGINT UNSIGNED NOT NULL REFERENCES room_types(id), capacity INTEGER NOT NULL CHECK(capacity > 0), maintenance_status VARCHAR(30) NOT NULL DEFAULT 'AVAILABLE');
CREATE TABLE room_rates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, room_type_id BIGINT UNSIGNED NOT NULL REFERENCES room_types(id), billing_unit VARCHAR(20) NOT NULL CHECK(billing_unit IN ('HALF_DAY','DAY')), amount_fcfa BIGINT NOT NULL CHECK(amount_fcfa >= 0), effective_from TIMESTAMP NOT NULL, effective_to TIMESTAMP, created_by BIGINT UNSIGNED REFERENCES users(id), CHECK(effective_to IS NULL OR effective_to > effective_from));
CREATE TABLE reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NOT NULL REFERENCES customers(id), room_id BIGINT UNSIGNED NOT NULL REFERENCES rooms(id), rate_id BIGINT UNSIGNED REFERENCES room_rates(id), start_date DATE NOT NULL, end_date DATE NOT NULL, start_time TIME, end_time TIME, billing_unit VARCHAR(20) NOT NULL CHECK(billing_unit IN ('HALF_DAY','DAY')), quantity NUMERIC(10,2) NOT NULL CHECK(quantity > 0), applied_unit_price_fcfa BIGINT NOT NULL, gross_fcfa BIGINT NOT NULL, discount_type VARCHAR(20), discount_value NUMERIC(12,2), discount_fcfa BIGINT NOT NULL DEFAULT 0, net_fcfa BIGINT NOT NULL, status VARCHAR(30) NOT NULL, created_by BIGINT UNSIGNED REFERENCES users(id), CHECK(end_date >= start_date), CHECK(net_fcfa >= 0));
CREATE TABLE reservation_occupants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reservation_id BIGINT UNSIGNED NOT NULL REFERENCES reservations(id), name VARCHAR(160) NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reservation_id BIGINT UNSIGNED NOT NULL REFERENCES reservations(id), amount_fcfa BIGINT NOT NULL CHECK(amount_fcfa > 0), method VARCHAR(40) NOT NULL, received_at TIMESTAMP NOT NULL, cashier_id BIGINT UNSIGNED REFERENCES users(id), status VARCHAR(30) NOT NULL, reference VARCHAR(120));
CREATE TABLE refunds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_id BIGINT UNSIGNED NOT NULL REFERENCES payments(id), amount_fcfa BIGINT NOT NULL CHECK(amount_fcfa > 0), reason TEXT NOT NULL, processed_by BIGINT UNSIGNED REFERENCES users(id), processed_at TIMESTAMP NOT NULL);
CREATE TABLE invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reservation_id BIGINT UNSIGNED NOT NULL REFERENCES reservations(id), invoice_number VARCHAR(60) UNIQUE NOT NULL, issued_at TIMESTAMP NOT NULL, gross_fcfa BIGINT NOT NULL, discount_fcfa BIGINT NOT NULL, net_fcfa BIGINT NOT NULL, snapshot_json JSON NOT NULL, status VARCHAR(30) NOT NULL);
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED REFERENCES users(id), action VARCHAR(120) NOT NULL, entity_type VARCHAR(120) NOT NULL, entity_id BIGINT NOT NULL, before_json JSON, after_json JSON, occurred_at TIMESTAMP NOT NULL);
CREATE INDEX idx_reservations_room_dates ON reservations(room_id,start_date,end_date);
CREATE INDEX idx_payments_reservation ON payments(reservation_id);
CREATE INDEX idx_rates_type_unit_effective ON room_rates(room_type_id,billing_unit,effective_from);
